/** The demo world manifest: "now", personas and counts. Object-shaped file; read first by every store. Fixture: world.json (core). */
export interface World {
  /** "world_flowd". */
  id: WorldId;
  /** Always 2026-10-03T14:00:00Z. Every relative time in the app is relative to this. */
  now: IsoTimestamp;
  /** 2026-07-05: day 0 of the 90-day history. */
  launch_date: IsoDate;
  /** Generator seed (stable output). */
  seed: number;
  /** Semver of the contract this data satisfies. */
  contract_version: string;
  personas: Personas;
  /** Row counts by fixture name. */
  counts: Record<string, number>;
}

/** A person who can sign in. Creators, brand members and admins are all users; role decides the experience. Fixture: users.json (core). */
export interface User {
  id: UserId;
  role: Role;
  /** Fictional addresses only (@example.com or @joinflowd.io for staff). */
  email: string;
  display_name: string;
  /** Generated avatar seed. */
  avatar: ArtSeed;
  auth_providers: AuthProvider[];
  status: UserStatus;
  /** Creators must be 18+. */
  age_verified: boolean;
  /** BCP-47, e.g. "en-US". */
  locale: string;
  /** IANA, e.g. "America/Chicago". */
  timezone: string;
  created_at: IsoTimestamp;
  last_seen_at?: IsoTimestamp;
  /** Job title for brand members and staff. */
  title?: string;
}

/** A creator profile (1:1 with a user whose role is creator). Tier, stats and reputation are earned, never bought. Fixture: creators.json (core). */
export interface Creator {
  id: CreatorId;
  /** -> users */
  user_id: UserId;
  /** Unique, lowercase, [a-z0-9._], no "@". Shown as @handle. Public link joinflowd.io/c/<handle>. */
  handle: string;
  display_name: string;
  bio: string;
  avatar: ArtSeed;
  /** 1 to 3. */
  niches: Niche[];
  country: Country;
  /** BCP-47 language tags. */
  languages: string[];
  /** Computed from the stats below (see FORMULAS: tier). Validated. */
  tier: Tier;
  tier_basis: TierBasis;
  tier_since: IsoTimestamp;
  /** Set when tier_basis = grace_hold: no tier drop before this (30 days after a dip). */
  tier_hold_until?: IsoTimestamp;
  /** Required when tier = elite (manual review). */
  tier_review?: TierReview;
  /** carry_over.cleared_cents + sum of the creator's cleared and paid earning rows in the ledger. Reconciled. */
  lifetime_cleared_cents: Cents;
  /** Approved submissions (status approved | posted | released), plus carry_over.approved_count. */
  approved_count: number;
  /** Finished decisions: approved + rejected (withdrawn and expired excluded), plus carry_over.decided_count. */
  decided_count: number;
  /** approved_count / decided_count, rounded to 2 decimals. Only finished work counts. */
  approval_rate: Ratio;
  /** 0..100 (see FORMULAS: creator reliability). */
  reliability_score: number;
  posts_count: number;
  /** Posts with status live. */
  live_posts_count: number;
  first_dollar_at?: IsoTimestamp;
  joined_at: IsoTimestamp;
  last_active_at: IsoTimestamp;
  /** One of the first 200 creators. */
  founding: boolean;
  /** Founding creators: end of the free instant cash-out perk (joined_at + 12 months). */
  founding_perks_until?: IsoTimestamp;
  badges: BadgeId[];
  /** Identity verification (JIT at first approval). */
  verification_status: VerificationStatus;
  onboarding_stage: OnboardingStage;
  /** True when identity, tax info and a payout method are all in place. */
  payout_ready: boolean;
  payout_method?: PayoutMethod;
  /** Mock Connect account id, "acct_<n>". */
  stripe_account_id?: string;
  /** Unique, e.g. "MAYA6". */
  referral_code: string;
  /** -> creators */
  referred_by_creator_id?: CreatorId;
  /** Snapshot of the current weekly streak (ext streaks.json must agree). */
  streak_weeks: number;
  /** Founding creators only: verified prior history that counts toward tier thresholds. */
  carry_over?: CarryOver;
  storefront: Storefront;
  /** 0 to 5 samples. */
  portfolio: PortfolioItem[];
  open_to_offers: boolean;
  /** Pause mode: preserves tier and streak. */
  paused_until?: IsoTimestamp;
}

